const lerp = (a, b, t) => a + (b - a) * t;
function coordinates(a, b, t) {
    const n = Math.max(a.length, b.length);
    const sample = (ps, i) => {
        if (ps.length === 1)
            return ps[0];
        const u = (i / (n - 1)) * (ps.length - 1), lo = Math.floor(u), hi = Math.min(ps.length - 1, lo + 1);
        return ps[lo].map((v, j) => lerp(v, ps[hi][j], u - lo));
    };
    return Array.from({ length: n }, (_, i) => {
        const u = sample(a, i), v = sample(b, i);
        return u.map((x, j) => lerp(x, v[j], t));
    });
}
function questionModel(id, progress) {
    const visual = cache.get(id.slice(2));
    if (!visual)
        throw Error(`문항 데이터 로딩 전 렌더링: ${id}`);
    progress = Math.max(0, Math.min(visual.steps.length - 1, progress));
    const lo = Math.floor(progress), hi = Math.ceil(progress), a = visual.steps[lo].model, b = visual.steps[hi].model, t = progress - lo;
    if (lo === hi)
        return a;
    const geometry = (aa, bb) => Array.from({ length: Math.max(aa.length, bb.length) }, (_, i) => {
        const x = aa[i], y = bb[i];
        if (!x)
            return { ...y, opacity: (y.opacity ?? 1) * t };
        if (!y)
            return { ...x, opacity: (x.opacity ?? 1) * (1 - t) };
        return {
            ...(t < 0.5 ? x : y),
            points: coordinates(x.points, y.points, t),
            opacity: lerp(x.opacity ?? 1, y.opacity ?? 1, t),
        };
    });
    return {
        ...(t < 0.5 ? a : b),
        range: a.range.map((v, i) => lerp(v, b.range[i], t)),
        lines: geometry(a.lines, b.lines),
        surfaces: geometry(a.surfaces, b.surfaces),
        dots: Array.from({ length: Math.max(a.dots.length, b.dots.length) }, (_, i) => {
            const x = a.dots[i], y = b.dots[i];
            if (!x)
                return { ...y, opacity: t };
            if (!y)
                return { ...x, opacity: 1 - t };
            return {
                ...(t < 0.5 ? x : y),
                at: x.at.map((v, j) => lerp(v, y.at[j], t)),
                size: lerp(x.size ?? 0.065, y.size ?? 0.065, t),
            };
        }),
    };
}

